#!/usr/bin/env python3
"""CapCut / 剪映 草稿导出（用 pyJianYingDraft 的真实模板做骨架）。"""
from __future__ import annotations

import os
from pathlib import Path

MARKER = "EFFECTCRAFT_OURS_CAPCUT_EXPORT_V2"

MODULE = '//! CapCut / 剪映 草稿导出：draft_content.json + draft_meta_info.json + 素材。\n\nuse serde_json::{Value, json};\n\nuse crate::{EngineError, Result, Session};\n\nconst TEMPLATE: &str = r##"{\n    "canvas_config": {\n        "height": 1080,\n        "ratio": "original",\n        "width": 1920\n    },\n    "color_space": 0,\n    "config": {\n        "adjust_max_index": 1,\n        "attachment_info": [],\n        "combination_max_index": 1,\n        "export_range": null,\n        "extract_audio_last_index": 1,\n        "lyrics_recognition_id": "",\n        "lyrics_sync": true,\n        "lyrics_taskinfo": [],\n        "maintrack_adsorb": true,\n        "material_save_mode": 0,\n        "multi_language_current": "none",\n        "multi_language_list": [],\n        "multi_language_main": "none",\n        "multi_language_mode": "none",\n        "original_sound_last_index": 1,\n        "record_audio_last_index": 1,\n        "sticker_max_index": 1,\n        "subtitle_keywords_config": null,\n        "subtitle_recognition_id": "",\n        "subtitle_sync": true,\n        "subtitle_taskinfo": [],\n        "system_font_list": [],\n        "video_mute": false,\n        "zoom_info_params": null\n    },\n    "cover": null,\n    "create_time": 0,\n    "duration": 0,\n    "extra_info": null,\n    "fps": 30.0,\n    "free_render_index_mode_on": false,\n    "group_container": null,\n    "id": "91E08AC5-22FB-47e2-9AA0-7DC300FAEA2B",\n    "keyframe_graph_list": [],\n    "keyframes": {\n        "adjusts": [],\n        "audios": [],\n        "effects": [],\n        "filters": [],\n        "handwrites": [],\n        "stickers": [],\n        "texts": [],\n        "videos": []\n    },\n    "last_modified_platform": {\n        "app_id": 3704,\n        "app_source": "lv",\n        "app_version": "5.9.0",\n        "os": "windows"\n    },\n    "platform": {\n        "app_id": 3704,\n        "app_source": "lv",\n        "app_version": "5.9.0",\n        "os": "windows"\n    },\n    "materials": {\n        "ai_translates": [],\n        "audio_balances": [],\n        "audio_effects": [],\n        "audio_fades": [],\n        "audio_track_indexes": [],\n        "audios": [],\n        "beats": [],\n        "canvases": [],\n        "chromas": [],\n        "color_curves": [],\n        "digital_humans": [],\n        "drafts": [],\n        "effects": [],\n        "flowers": [],\n        "green_screens": [],\n        "handwrites": [],\n        "hsl": [],\n        "images": [],\n        "log_color_wheels": [],\n        "loudnesses": [],\n        "manual_deformations": [],\n        "masks": [],\n        "material_animations": [],\n        "material_colors": [],\n        "multi_language_refs": [],\n        "placeholders": [],\n        "plugin_effects": [],\n        "primary_color_wheels": [],\n        "realtime_denoises": [],\n        "shapes": [],\n        "smart_crops": [],\n        "smart_relights": [],\n        "sound_channel_mappings": [],\n        "speeds": [],\n        "stickers": [],\n        "tail_leaders": [],\n        "text_templates": [],\n        "texts": [],\n        "time_marks": [],\n        "transitions": [],\n        "video_effects": [],\n        "video_trackings": [],\n        "videos": [],\n        "vocal_beautifys": [],\n        "vocal_separations": []\n    },\n    "mutable_config": null,\n    "name": "",\n    "new_version": "110.0.0",\n    "relationships": [],\n    "render_index_track_mode_on": false,\n    "retouch_cover": null,\n    "source": "default",\n    "static_cover_image_path": "",\n    "time_marks": null,\n    "tracks": [\n    ],\n    "update_time": 0,\n    "version": 360000\n}"##;\nconst META: &str = r##"{\n\t"cloud_package_completed_time": "",\n\t"draft_cloud_capcut_purchase_info": "",\n\t"draft_cloud_last_action_download": false,\n\t"draft_cloud_materials": [],\n\t"draft_cloud_purchase_info": "",\n\t"draft_cloud_template_id": "",\n\t"draft_cloud_tutorial_info": "",\n\t"draft_cloud_videocut_purchase_info": "",\n\t"draft_cover": "",\n\t"draft_deeplink_url": "",\n\t"draft_enterprise_info": {\n\t\t"draft_enterprise_extra": "",\n\t\t"draft_enterprise_id": "",\n\t\t"draft_enterprise_name": "",\n\t\t"enterprise_material": []\n\t},\n\t"draft_fold_path": "",\n\t"draft_id": "BC69C7CD-7C5E-4185-B284-AF3E1047A664",\n\t"draft_is_ai_packaging_used": false,\n\t"draft_is_ai_shorts": false,\n\t"draft_is_ai_translate": false,\n\t"draft_is_article_video_draft": false,\n\t"draft_is_from_deeplink": "false",\n\t"draft_is_invisible": false,\n\t"draft_materials": [\n\t\t{\n\t\t\t"type": 0,\n\t\t\t"value": []\n\t\t},\n\t\t{\n\t\t\t"type": 1,\n\t\t\t"value": []\n\t\t},\n\t\t{\n\t\t\t"type": 2,\n\t\t\t"value": []\n\t\t},\n\t\t{\n\t\t\t"type": 3,\n\t\t\t"value": []\n\t\t},\n\t\t{\n\t\t\t"type": 6,\n\t\t\t"value": []\n\t\t},\n\t\t{\n\t\t\t"type": 7,\n\t\t\t"value": []\n\t\t},\n\t\t{\n\t\t\t"type": 8,\n\t\t\t"value": []\n\t\t}\n\t],\n\t"draft_materials_copied_info": [],\n\t"draft_name": "",\n\t"draft_new_version": "",\n\t"draft_removable_storage_device": "",\n\t"draft_root_path": "",\n\t"draft_segment_extra_info": [],\n\t"draft_type": "",\n\t"tm_draft_cloud_completed": "",\n\t"tm_draft_cloud_modified": 0,\n\t"tm_draft_removed": 0,\n\t"tm_duration": 0\n}"##;\n\nfn uid(n: &mut u64) -> String {\n    *n += 1;\n    format!("{:032x}", n.wrapping_mul(0x9E37_79B9_7F4A_7C15u64))\n}\n\nfn us(t: effectcraft_time::Tick) -> i64 {\n    (t.seconds() * 1_000_000.0).round() as i64\n}\n\nfn is_audio(path: &str) -> bool {\n    let p = path.to_ascii_lowercase();\n    p.ends_with(".mp3") || p.ends_with(".wav") || p.ends_with(".m4a") || p.ends_with(".aac") || p.ends_with(".flac")\n}\n\npub(crate) fn export(s: &mut Session, p: &Value) -> Result<Value> {\n    let cid = super::comp_id(s, p)?;\n    let comp = s.project.comp(cid).ok_or(EngineError::NoComp)?.clone();\n    let mut n = 0u64;\n    let mut videos: Vec<Value> = Vec::new();\n    let mut segments: Vec<Value> = Vec::new();\n    let mut files: Vec<(String, String)> = Vec::new();\n    let fps = comp.frame_rate.as_f64().max(1.0);\n    for layer in comp.layers.iter().rev() {\n        let Some(item_id) = layer.source.item() else { continue };\n        let Some(item) = s.project.item(item_id) else { continue };\n        let effectcraft_project::ItemKind::Footage(f) = &item.kind else { continue };\n        if f.missing || f.path.is_empty() {\n            continue;\n        }\n        let src_len = us(layer.out_point) - us(layer.in_point);\n        if src_len <= 0 {\n            continue;\n        }\n        let audio = is_audio(&f.path);\n        let local = format!("{:032x}", n.wrapping_add(1));\n        let material_id = uid(&mut n);\n        let name = std::path::Path::new(&f.path)\n            .file_name()\n            .and_then(|x| x.to_str())\n            .unwrap_or("media")\n            .to_string();\n        videos.push(json!({\n            "audio_fade": null,\n            "category_id": "",\n            "category_name": "local",\n            "check_flag": 63487,\n            "crop": {\n                "lower_left_x": 0.0, "lower_left_y": 1.0,\n                "lower_right_x": 1.0, "lower_right_y": 1.0,\n                "upper_left_x": 0.0, "upper_left_y": 0.0,\n                "upper_right_x": 1.0, "upper_right_y": 0.0\n            },\n            "crop_ratio": "free",\n            "crop_scale": 1.0,\n            "duration": us(f.duration),\n            "height": f.height,\n            "id": material_id.clone(),\n            "local_material_id": local,\n            "material_id": material_id.clone(),\n            "material_name": name.clone(),\n            "media_path": "",\n            "path": f.path.clone(),\n            "type": if audio { "extract_audio" } else { "video" },\n            "width": f.width\n        }));\n        let start = us(layer.start_time).max(0);\n        let src_off = (us(layer.in_point) - us(layer.start_time)).max(0);\n        segments.push(json!({\n            "common_keyframes": [],\n            "enable_adjust": true,\n            "enable_color_correct_adjust": false,\n            "enable_color_curves": true,\n            "enable_color_match_adjust": false,\n            "enable_color_wheels": true,\n            "enable_lut": true,\n            "enable_smart_color_adjust": false,\n            "id": uid(&mut n),\n            "keyframe_refs": [],\n            "last_nonzero_volume": 1.0,\n            "material_id": material_id,\n            "render_index": 0,\n            "reverse": false,\n            "source_timerange": { "duration": src_len, "start": src_off },\n            "speed": 1.0,\n            "target_timerange": { "duration": src_len, "start": start },\n            "track_attribute": 0,\n            "track_render_index": 0,\n            "visible": true,\n            "volume": 1.0\n        }));\n        files.push((f.path.clone(), name));\n    }\n    if segments.is_empty() {\n        return Err(EngineError::Other("这个工程没有可导出的素材图层".into()));\n    }\n    let mut content: Value = serde_json::from_str(TEMPLATE).map_err(|e| EngineError::Other(format!("{e}")))?;\n    let mut meta_json: Value = serde_json::from_str(META).map_err(|e| EngineError::Other(format!("{e}")))?;\n    let duration = us(comp.duration);\n    if let Some(o) = content.as_object_mut() {\n        o.insert("canvas_config".into(), json!({"height": comp.height, "ratio": "original", "width": comp.width}));\n        o.insert("duration".into(), json!(duration));\n        o.insert("fps".into(), json!(fps));\n        o.insert("id".into(), json!(uid(&mut n)));\n        o.insert("name".into(), json!(comp.name.clone()));\n        o.insert("tracks".into(), json!([{\n            "attribute": 0,\n            "flag": 0,\n            "id": uid(&mut n),\n            "is_default_name": true,\n            "name": "",\n            "segments": segments,\n            "type": "video"\n        }]));\n        if let Some(m) = o.get_mut("materials").and_then(|m| m.as_object_mut()) {\n            m.insert("videos".into(), json!(videos));\n        }\n    }\n    if let Some(o) = meta_json.as_object_mut() {\n        o.insert("draft_name".into(), json!(comp.name.clone()));\n        o.insert("draft_duration".into(), json!(duration));\n    }\n    let zip_path = format!("/storage/emulated/0/DCIM/EffectCraft/{}-CapCut工程.zip", comp.name);\n    let file = std::fs::File::create(&zip_path).map_err(|e| EngineError::Other(format!("{e}")))?;\n    let mut zip = zip::ZipWriter::new(file);\n    let opts = zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated);\n    use std::io::Write;\n    zip.start_file("draft_content.json", opts).map_err(|e| EngineError::Other(format!("{e}")))?;\n    zip.write_all(serde_json::to_string_pretty(&content).unwrap_or_default().as_bytes()).ok();\n    zip.start_file("draft_meta_info.json", opts).map_err(|e| EngineError::Other(format!("{e}")))?;\n    zip.write_all(serde_json::to_string_pretty(&meta_json).unwrap_or_default().as_bytes()).ok();\n    for (path, name) in files {\n        let Ok(bytes) = std::fs::read(&path) else { continue };\n        zip.start_file(format!("materials/{name}"), opts).ok();\n        zip.write_all(&bytes).ok();\n    }\n    zip.finish().map_err(|e| EngineError::Other(format!("{e}")))?;\n    Ok(json!({"zip": zip_path}))\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn template_parses() {\n        let v: Value = serde_json::from_str(TEMPLATE).expect("draft_content template");\n        assert!(v.get("materials").is_some());\n        assert!(v.get("canvas_config").is_some());\n        let m: Value = serde_json::from_str(META).expect("draft_meta_info");\n        assert!(m.is_object());\n    }\n}\n'

MOD_ANCHOR = "pub(crate) mod ours_export;\n"
SPEC_ANCHOR = "        share_file\n    )]\n}"
SPEC_NEW = """        share_file
    ), cmd!(
        "ours.exportCapCut",
        "导出 CapCut 工程包(.zip)",
        ["File", "Export"],
        None,
        "{comp?}",
        always,
        super::ours_capcut::export
    )]
}"""


def main() -> None:
    root = Path(os.environ["EFFECTCRAFT_DIR"]).resolve()
    mod_rs = root / "crates/engine/src/cmd.rs"
    src = mod_rs.read_text(encoding="utf-8")
    if MARKER in src:
        print("capcut export already installed")
        return
    if "pub(crate) mod ours_capcut;" not in src:
        mod_rs.write_text(src.replace(MOD_ANCHOR, MOD_ANCHOR + "pub(crate) mod ours_capcut;\n", 1), encoding="utf-8")
    (root / "crates/engine/src/cmd/ours_capcut.rs").write_text(MODULE, encoding="utf-8")
    specs = root / "crates/engine/src/cmd/ours_export.rs"
    s2 = specs.read_text(encoding="utf-8")
    if s2.count(SPEC_ANCHOR) != 1:
        raise SystemExit(f"specs anchor: {s2.count(SPEC_ANCHOR)}")
    specs.write_text(s2.replace(SPEC_ANCHOR, SPEC_NEW, 1), encoding="utf-8")
    print("capcut export installed")


if __name__ == "__main__":
    main()
